package exam; public class FinalizationRepository {private final Store store;public FinalizationRepository(Store s){store=s;}public void save(Finalization e){store.put("finalization",e.id,e.status().name(),e.detail);}public Finalization find(String id){String[] row=store.get("finalization",id);return row==null?null:new Finalization(id,row[1],Finalization.Status.valueOf(row[0]));}}
